package mx.gob.sedesol.basegestor.gestionescolar.v2;
import static org.testng.Assert.*; import java.util.Date; import org.testng.annotations.Test; import mx.gob.sedesol.basegestor.commons.dto.gestionescolar.v2.*; import mx.gob.sedesol.basegestor.service.impl.gestionescolar.v2.EvaluacionCurricularV2ServiceImpl;
/** F5E-C-01 a F5E-C-16: impedimentos y extraordinarios, sólo en sombra. */
public class EvaluacionCurricularV2Fase5ETest { private final EvaluacionCurricularV2ServiceImpl s=new EvaluacionCurricularV2ServiceImpl();
 @Test public void f5EC01Rn64NoProcede(){ContextoEvaluacionCurricularV2DTO z=c();z.getUnidades().add(r(2,2));z.getUnidades().add(r(3,3));z.getUnidades().add(r(4,4));noProcede(z,"RN_6_4_REZAGO_SEVERO");}
 @Test public void f5EC02SeriacionDirectaNoProcedeUd(){ContextoEvaluacionCurricularV2DTO z=c();z.getUnidades().get(1).setSeriacionDirectaConocida(Boolean.TRUE);noProcede(z,"SERIACION_DIRECTA_O_INDIRECTA");}
 @Test public void f5EC03SeriacionIndirectaNoProcedeUd(){ContextoEvaluacionCurricularV2DTO z=c();z.getUnidades().get(1).setSeriacionIndirectaConocida(Boolean.TRUE);noProcede(z,"SERIACION_DIRECTA_O_INDIRECTA");}
 @Test public void f5EC04SancionNoProcede(){ContextoEvaluacionCurricularV2DTO z=c();z.setSancionImpedimentoRegistrada(Boolean.TRUE);noProcede(z,"SANCION_IMPEDITIVA");}
 @Test public void f5EC05RestriccionPeNoProcede(){ContextoEvaluacionCurricularV2DTO z=c();z.setRestriccionPeNormativaImpeditiva(Boolean.TRUE);z.setCodigoRestriccionPeNormativa("PE-X");z.setFuenteRestriccionPeNormativa("PE2027");noProcede(z,"RESTRICCION_PE_NORMATIVA:PE-X:PE2027");}
 @Test public void f5EC06RestriccionNormativaNoProcede(){ContextoEvaluacionCurricularV2DTO z=c();z.setRestriccionPeNormativaImpeditiva(Boolean.TRUE);z.setCodigoRestriccionPeNormativa("NORMA-X");z.setFuenteRestriccionPeNormativa("NORMATIVA");noProcede(z,"RESTRICCION_PE_NORMATIVA:NORMA-X:NORMATIVA");}
 @Test public void f5EC07RestriccionDesconocidaRevision(){ContextoEvaluacionCurricularV2DTO z=c();z.setRestriccionPeNormativaConocida(null);assertEquals(x(z).getEstadoResolucionAvance(),EstadoResolucionAvanceV2.REQUIERE_REVISION);}
 @Test public void f5EC08CuatroImpedimentosConcurrentes(){ContextoEvaluacionCurricularV2DTO z=c();z.getUnidades().add(r(2,2));z.getUnidades().add(r(3,3));z.getUnidades().add(r(4,4));z.getUnidades().get(1).setSeriacionDirectaConocida(Boolean.TRUE);z.setSancionImpedimentoRegistrada(Boolean.TRUE);z.setRestriccionPeNormativaImpeditiva(Boolean.TRUE);EvaluacionCargaAcademicaV2DTO q=x(z);assertEquals(q.getEstadoResolucionAvance(),EstadoResolucionAvanceV2.NO_PROCEDE_AVANCE_CONDICIONADO);assertEquals(q.getImpedimentosAvanceRn615().size(),4);}
 @Test public void f5EC09TipificadoContinuaOrdinario(){assertEquals(x(c()).getEstadoResolucionAvance(),EstadoResolucionAvanceV2.CONTINUA_EVALUACION_ORDINARIA_RN61);}
 @Test public void f5EC10DatosInsuficientesNoExtraordinario(){ContextoEvaluacionCurricularV2DTO z=c();z.setSancionImpedimentoConocida(null);assertEquals(x(z).getEstadoResolucionAvance(),EstadoResolucionAvanceV2.REQUIERE_REVISION);}
 @Test public void f5EC11SinEfectoProductivo(){assertFalse(s.evaluarSombra(c()).getEfectosProductivosAplicados());}
 @Test public void f5EC12Determinista(){assertEquals(x(c()).getEstadoResolucionAvance(),x(c()).getEstadoResolucionAvance());}
 private void noProcede(ContextoEvaluacionCurricularV2DTO z,String i){EvaluacionCargaAcademicaV2DTO q=x(z);assertEquals(q.getEstadoResolucionAvance(),EstadoResolucionAvanceV2.NO_PROCEDE_AVANCE_CONDICIONADO);assertTrue(q.getImpedimentosAvanceRn615().contains(i));} private EvaluacionCargaAcademicaV2DTO x(ContextoEvaluacionCurricularV2DTO z){return s.evaluarSombra(z).getEvaluacionCargaAcademica();}
 private ContextoEvaluacionCurricularV2DTO c(){ContextoEvaluacionCurricularV2DTO z=new ContextoEvaluacionCurricularV2DTO();z.setIdPlan(1L);z.setPeriodoNormativo("2027-1");z.setSemestreObjetivo(5);z.setVersionReglas("PE2027-V1");z.setFechaEvaluacion(new Date(0));z.setActividadAcademicaComprobada(true);z.setPermanenciaDentroLimiteComprobada(true);z.setSeriacionComprobada(true);z.setEstructuraProgramaEducativoComprobada(true);z.setSancionImpedimentoConocida(true);z.setSancionImpedimentoRegistrada(false);z.setRestriccionPeNormativaConocida(true);z.setRestriccionPeNormativaImpeditiva(false);z.getUnidades().add(r(1,1));z.getUnidades().add(u(50,5));return z;} private UnidadEvaluacionCurricularV2DTO r(long i,int se){UnidadEvaluacionCurricularV2DTO u=u(i,se);u.setEstado(EstadoUnidadCurricularV2.REPROBADA);u.setCausa(CausaPendienteUnidadV2.REPROBACION);u.setReprobacionVigenteConocida(true);u.setReprobacionPeriodoPrevioConocida(true);return u;}private UnidadEvaluacionCurricularV2DTO u(long i,int se){UnidadEvaluacionCurricularV2DTO u=new UnidadEvaluacionCurricularV2DTO();u.setIdPrograma(i);u.setClave("U"+i);u.setTipoUd("Obligatoria");u.setSemestre(se);u.setEstado(EstadoUnidadCurricularV2.NO_CURSADA);u.setCausa(CausaPendienteUnidadV2.NO_CURSAMIENTO);u.setOfertada(true);u.setGrupoActivoConocido(true);u.setCupoDisponibleConocido(true);return u;}}
